// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.entityimport androidx.room.ColumnInfoimport androidx.room.Entityimport androidx.room.ForeignKeyimport androidx.room.Indeximport androidx.room.PrimaryKey/** * NOUS — Memory embedding (Table 16, v2). * * Stores INT8 quantized vectors SEPARATELY from episodic_memories to * prevent OOM on bulk SELECT. 384-dim vector compressed from 1536 bytes * (float32) to 386 bytes (INT8 + scale). * * @see <a href="docs/strategy/module-3-strategy-v2.md">§9 Vector Storage</a> */@Entity(    tableName = "memory_embeddings",    indices = [Index("embedding_model_version")],    foreignKeys = [        ForeignKey(            entity = EpisodicMemoryEntity::class,            parentColumns = ["id"],            childColumns = ["memory_id"],            onDelete = ForeignKey.CASCADE,        ),    ],)data class MemoryEmbeddingEntity(    @PrimaryKey    @ColumnInfo(name = "memory_id")    val memoryId: Long,    @ColumnInfo(name = "embedding")    val embedding: ByteArray,  // INT8 quantized (386 bytes for 384-dim)    @ColumnInfo(name = "embedding_model_version")    val embeddingModelVersion: String,    @ColumnInfo(name = "created_at")    val createdAt: Long,) {    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (javaClass != other?.javaClass) return false        val o = other as? MemoryEmbeddingEntity ?: return false        return memoryId == o.memoryId    }    override fun hashCode(): Int = memoryId.hashCode()}/** * NOUS — Procedural memory (Table 3). * * How-to knowledge, skill patterns. Never decays. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§3 Memory Architecture</a> */@Entity(tableName = "procedural_memories")data class ProceduralMemoryEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "skill_id")    val skillId: String,    @ColumnInfo(name = "intent_type")    val intentType: String,    @ColumnInfo(name = "procedure")    val procedure: String,    @ColumnInfo(name = "success_count")    val successCount: Int = 0,    @ColumnInfo(name = "failure_count")    val failureCount: Int = 0,    @ColumnInfo(name = "last_used")    val lastUsed: Long? = null,    @ColumnInfo(name = "confidence_alpha")    val confidenceAlpha: Float = 1.0f,    @ColumnInfo(name = "confidence_beta")    val confidenceBeta: Float = 1.0f,    @ColumnInfo(name = "is_deleted")    val isDeleted: Boolean = false,    @ColumnInfo(name = "created_at")    val createdAt: Long,    @ColumnInfo(name = "updated_at")    val updatedAt: Long,) {    val confidence: Float        get() = confidenceAlpha / (confidenceAlpha + confidenceBeta)}/** * NOUS — Prospective memory (Table 4). * * Future intentions, reminders. Expires after trigger time. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§3 Memory Architecture</a> */@Entity(tableName = "prospective_memories")data class ProspectiveMemoryEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "description")    val description: String,    @ColumnInfo(name = "trigger_type")    val triggerType: String,  // time, location, event    @ColumnInfo(name = "trigger_data")    val triggerData: String,  // JSON    @ColumnInfo(name = "is_recurring")    val isRecurring: Boolean = false,    @ColumnInfo(name = "recurrence_rule")    val recurrenceRule: String? = null,  // iCal RRULE    @ColumnInfo(name = "status")    val status: String = "pending",  // pending, fired, expired, cancelled    @ColumnInfo(name = "created_at")    val createdAt: Long,    @ColumnInfo(name = "fired_at")    val firedAt: Long? = null,    @ColumnInfo(name = "expires_at")    val expiresAt: Long? = null,)/** * NOUS — User fact (Table 10). * * Long-term user preferences. Bayesian confidence. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "user_facts",    indices = [Index(value = ["key"], unique = true)],)data class UserFactEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "key")    val key: String,  // "name", "occupation", "timezone"    @ColumnInfo(name = "value")    val value: String,    @ColumnInfo(name = "confidence_alpha")    val confidenceAlpha: Float = 1.0f,    @ColumnInfo(name = "confidence_beta")    val confidenceBeta: Float = 1.0f,    @ColumnInfo(name = "source")    val source: String,    @ColumnInfo(name = "learned_at")    val learnedAt: Long,    @ColumnInfo(name = "last_confirmed")    val lastConfirmed: Long? = null,    @ColumnInfo(name = "is_deleted")    val isDeleted: Boolean = false,    @ColumnInfo(name = "created_at")    val createdAt: Long,    @ColumnInfo(name = "updated_at")    val updatedAt: Long,) {    val confidence: Float        get() = confidenceAlpha / (confidenceAlpha + confidenceBeta)}/** * NOUS — LLM cache entry (Table 15). * * Semantic cache for LLM responses. INT8 quantized prompt embedding. * Supports volatile TTL (5 min for time-sensitive queries). * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "llm_cache",    indices = [        Index(value = ["prompt_hash"], unique = true),        Index("expires_at"),        Index("model_id"),    ],)data class LlmCacheEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "prompt_hash")    val promptHash: String,    @ColumnInfo(name = "prompt_preview")    val promptPreview: String? = null,    @ColumnInfo(name = "prompt_embedding")    val promptEmbedding: ByteArray,  // INT8 quantized    @ColumnInfo(name = "response")    val response: String,    @ColumnInfo(name = "model_id")    val modelId: String,    @ColumnInfo(name = "embedding_model_version")    val embeddingModelVersion: String,    @ColumnInfo(name = "is_volatile")    val isVolatile: Boolean = false,    @ColumnInfo(name = "hit_count")    val hitCount: Int = 0,    @ColumnInfo(name = "created_at")    val createdAt: Long,    @ColumnInfo(name = "expires_at")    val expiresAt: Long,    @ColumnInfo(name = "last_accessed")    val lastAccessed: Long,) {    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (javaClass != other?.javaClass) return false        val o = other as? LlmCacheEntity ?: return false        return id == o.id    }    override fun hashCode(): Int = id.hashCode()}